// Catalogue : blocs > series > cartes
// Prix en euros (ex: 15 = 15 EUR, 0.5 = 50 centimes)
// Ajoute / modifie librement.

export type Condition = "Mint" | "Near Mint" | "Excellent" | "Good" | "Played";
export type Rarity =
  | "Reverse"
  | "Holo"
  | "Holo Cracked Ice"
  | "Holo ligne"
  | "Rare Reverse"
  | "Rare Holo"
  | "Ultra Rare"
  | "Secrete";

export type Bloc = {
  id: string;
  name: string;
  tagline: string;
  coverColor: string; // classes tailwind gradient
  image?: string;
  imageFit?: "cover" | "contain"; // cover (par defaut) remplit, contain affiche l'image entiere
};

export type Serie = {
  id: string;
  blocId: string;
  code: string; // ex: EV09
  name: string;
  releaseYear: number;
  image?: string;
};

export type CardVariant = {
  rarity: Rarity;
  price: number;
  stock: number;
};

export type VariantKey = "base" | "alt";

export type Card = {
  id: string;
  serieId: string;
  name: string;
  number: string; // ex: 025/198
  rarity: Rarity;
  condition: Condition;
  language: "FR" | "EN" | "JP";
  price: number;
  stock: number;
  image?: string;
  description?: string;
  altVariant?: CardVariant; // deuxieme version (ex: Rare Holo a cote d'un Rare Reverse)
};

export function resolveVariant(card: Card, key: VariantKey = "base"): CardVariant {
  if (key === "alt" && card.altVariant) return card.altVariant;
  return { rarity: card.rarity, price: card.price, stock: card.stock };
}

